sed -n '1,320p' /artifacts/frontend/src/pages.jsx"","aggregated_output":"import express from 'express';
import fs from 'node:fs';
import path from 'node:path';
import { z } from 'zod';
import { SNAPSHOT_DIR } from '../db/index.js';
import * as Bookmarks from '../models/bookmarks.js';
import { setBookmarkTags, addBookmarkTags, removeBookmarkTags } from '../models/tags.js';
import { getPreferences } from '../models/preferences.js';
import { normalizeUrl, isValidWebUrl, fallbackTitle } from '../url/normalize.js';
import { searchIds } from '../services/search.js';
import { enrich } from '../services/enrichment.js';
import { captureSnapshot } from '../services/snapshot.js';
import { saveToArchiveOrg } from '../services/archiveOrg.js';
import { invalidUrl, duplicate, invalidQuery, notFound, validationError } from './errors.js';

const router = express.Router();

// ---- Background jobs (fire-and-forget; outcomes recorded and surfaced, FR-041) ----

export async function runEnrichment(id, url, opts = {}) {
  try {
    const result = await enrich(id, url);
    Bookmarks.setEnrichment(id, { ...result, ...opts });
  } catch {
    // enrichment is best-effort; fallback title already stored
  }
}

export async function runSnapshot(id, url) {
  Bookmarks.setSnapshot(id, { path: null, kind: null, status: 'pending' });
  try {
    const { path: p, kind } = await captureSnapshot(id, url);
    Bookmarks.setSnapshot(id, { path: p, kind, status: 'ready' });
  } catch {
    Bookmarks.setSnapshot(id, { path: null, kind: null, status: 'failed' });
  }
}

export async function runArchiveOrg(id, url) {
  Bookmarks.setArchiveOrg(id, { url: null, status: 'pending' });
  try {
    const archivedUrl = await saveToArchiveOrg(url);
    Bookmarks.setArchiveOrg(id, { url: archivedUrl, status: 'ready' });
  } catch {
    Bookmarks.setArchiveOrg(id, { url: null, status: 'failed' });
  }
}

function kickoff(id, url, opts = {}) {
  // Test hook: skip background browser/network jobs during automated runs.
  if (process.env.BOOKMARKS_DISABLE_JOBS === '1') return;
  // Do not block the response; each job records its own outcome.
  runEnrichment(id, url, opts);
  runSnapshot(id, url);
}

// ---- Query parsing helpers ----

function parseListOptions(req, { archived = false } = {}) {
  const prefs = getPreferences();
  const q = req.query.q ? String(req.query.q) : '';
  const splitTags = (v) =>
    v ? String(v).split(',').map((t) => t.trim()).filter(Boolean) : [];
  const sort = req.query.sort ? String(req.query.sort) : prefs.defaultSort;
  const pageSize = req.query.pageSize ? Number(req.query.pageSize) : prefs.itemsPerPage;
  const page = req.query.page ? Number(req.query.page) : 1;

  let matchIds = null;
  if (q.trim()) {
    matchIds = searchIds(q); // throws invalid_query on malformed
  }

  return {
    q,
    matchIds,
    includeTags: splitTags(req.query.includeTags),
    excludeTags: splitTags(req.query.excludeTags),
    unread: String(req.query.unread) === 'true',
    archived,
    sort,
    page: Number.isFinite(page) ? page : 1,
    pageSize: Number.isFinite(pageSize) ? pageSize : 25,
  };
}

// ---- Routes ----

const createSchema = z.object({
  url: z.string(),
  title: z.string().optional(),
  description: z.string().optional(),
  tags: z.array(z.string()).optional(),
  note: z.string().optional(),
});

router.post('/', (req, res, next) => {
  try {
    const body = createSchema.parse(req.body);
    if (!isValidWebUrl(body.url)) throw invalidUrl();
    const urlKey = normalizeUrl(body.url);

    const existing = Bookmarks.getByUrlKey(urlKey);
    if (existing) throw duplicate(existing.id); // route to existing (FR-006)

    const id = Bookmarks.create({
      url: body.url.trim(),
      urlKey,
      title: body.title || fallbackTitle(body.url),
      description: body.description || '',
      note: body.note || null,
      tags: body.tags || [],
    });
    // Auto-collect only the fields the user did not provide (FR-004).
    kickoff(id, body.url.trim(), {
      overrideTitle: !body.title,
      overrideDescription: !body.description,
    });
    res.status(201).json(Bookmarks.getById(id));
  } catch (err) {
    if (err instanceof z.ZodError) return next(validationError());
    next(err);
  }
});

router.get('/', (req, res, next) => {
  try {
    const options = parseListOptions(req);
    res.json(Bookmarks.list(options));
  } catch (err) {
    if (err && err.code === 'invalid_query') return next(invalidQuery(err.message));
    next(err);
  }
});

router.get('/archived', (req, res, next) => {
  try {
    const options = parseListOptions(req, { archived: true });
    res.json(Bookmarks.list(options));
  } catch (err) {
    if (err && err.code === 'invalid_query') return next(invalidQuery(err.message));
    next(err);
  }
});

// Bulk actions (FR-026, FR-026a, FR-027).
const bulkSchema = z.object({
  target: z.object({
    ids: z.array(z.number()).optional(),
    filter: z.record(z.any()).optional(),
  }),
  action: z.enum(['addTags', 'removeTags', 'markRead', 'markUnread', 'archive', 'delete']),
  tags: z.array(z.string()).optional(),
});

router.post('/bulk', (req, res, next) => {
  try {
    const body = bulkSchema.parse(req.body);
    let ids = [];
    if (body.target.ids && body.target.ids.length) {
      ids = body.target.ids;
    } else if (body.target.filter) {
      const f = body.target.filter;
      const opts = {
        archived: !!f.archived,
        unread: !!f.unread,
        includeTags: f.includeTags || [],
        excludeTags: f.excludeTags || [],
        matchIds: f.q && String(f.q).trim() ? searchIds(String(f.q)) : null,
      };
      ids = Bookmarks.resolveIds(opts);
    }

    if ((body.action === 'addTags' || body.action === 'removeTags') && !body.tags) {
      throw validationError('tags are required for tag actions.');
    }

    for (const id of ids) {
      switch (body.action) {
        case 'addTags':
          addBookmarkTags(id, body.tags);
          break;
        case 'removeTags':
          removeBookmarkTags(id, body.tags);
          break;
        case 'markRead':
          Bookmarks.setReadState(id, false);
          break;
        case 'markUnread':
          Bookmarks.setReadState(id, true);
          break;
        case 'archive':
          Bookmarks.setArchived(id, true);
          break;
        case 'delete':
          removeWithFiles(id);
          break;
        default:
          break;
      }
    }
    res.json({ affected: ids.length });
  } catch (err) {
    if (err instanceof z.ZodError) return next(validationError());
    if (err && err.code === 'invalid_query') return next(invalidQuery(err.message));
    next(err);
  }
});

router.get('/:id', (req, res, next) => {
  const bm = Bookmarks.getById(Number(req.params.id));
  if (!bm) return next(notFound('Bookmark not found.'));
  res.json(bm);
});

const patchSchema = z.object({
  url: z.string().optional(),
  title: z.string().optional(),
  description: z.string().optional(),
  tags: z.array(z.string()).optional(),
  note: z.string().nullable().optional(),
});

router.patch('/:id', (req, res, next) => {
  try {
    const id = Number(req.params.id);
    const row = Bookmarks.getRowById(id);
    if (!row) throw notFound('Bookmark not found.');
    const body = patchSchema.parse(req.body);

    const fields = {};
    if (body.url !== undefined) {
      if (!isValidWebUrl(body.url)) throw invalidUrl();
      const urlKey = normalizeUrl(body.url);
      const existing = Bookmarks.getByUrlKey(urlKey);
      if (existing && existing.id !== id) throw duplicate(existing.id);
      fields.url = body.url.trim();
      fields.url_key = urlKey;
    }
    if (body.title !== undefined) fields.title = body.title;
    if (body.description !== undefined) fields.description = body.description;
    if (body.note !== undefined) fields.note_md = body.note;

    if (Object.keys(fields).length) Bookmarks.updateFields(id, fields);
    if (body.tags !== undefined) setBookmarkTags(id, body.tags);

    // If the address changed, refresh the snapshot and favicon/preview for the new
    // page, but never override the user's title/description (FR-004).
    if (fields.url) {
      runSnapshot(id, fields.url);
      runEnrichment(id, fields.url, { overrideTitle: false, overrideDescription: false });
    }

    res.json(Bookmarks.getById(id));
  } catch (err) {
    if (err instanceof z.ZodError) return next(validationError());
    next(err);
  }
});

function removeWithFiles(id) {
  Bookmarks.remove(id);
  const dir = path.join(SNAPSHOT_DIR, String(id));
  fs.rmSync(dir, { recursive: true, force: true });
}

router.delete('/:id', (req, res, next) => {
  const id = Number(req.params.id);
  if (!Bookmarks.getRowById(id)) return next(notFound('Bookmark not found.'));
  removeWithFiles(id);
  res.status(204).end();
});

router.post('/:id/read-state', (req, res, next) => {
  const id = Number(req.params.id);
  if (!Bookmarks.getRowById(id)) return next(notFound('Bookmark not found.'));
  res.json(Bookmarks.setReadState(id, !!req.body.unread));
});

router.post('/:id/archive', (req, res, next) => {
  const id = Number(req.params.id);
  if (!Bookmarks.getRowById(id)) return next(notFound('Bookmark not found.'));
  res.json(Bookmarks.setArchived(id, true));
});

router.post('/:id/restore', (req, res, next) => {
  const id = Number(req.params.id);
  if (!Bookmarks.getRowById(id)) return next(notFound('Bookmark not found.'));
  res.json(Bookmarks.setArchived(id, false));
});

router.post('/:id/archive-org', (req, res, next) => {
  const id = Number(req.params.id);
  const row = Bookmarks.getRowById(id);
  if (!row) return next(notFound('Bookmark not found.'));
  runArchiveOrg(id, row.url); // out-of-band; sets pending then ready|failed
  res.json(Bookmarks.getById(id));
});

export default router;
import { stmt } from '../db/index.js';
import { getTagsForBookmark, setBookmarkTags } from './tags.js';
import { renderNote } from '../services/markdown.js';

const SORTS = {
  created_desc: 'b.created_at DESC, b.id DESC',
  created_asc: 'b.created_at ASC, b.id ASC',
  title_asc: 'b.title COLLATE NOCASE ASC, b.id ASC',
  title_desc: 'b.title COLLATE NOCASE DESC, b.id DESC',
};

export function sortClause(sort) {
  return SORTS[sort] || SORTS.created_desc;
}

/** Map a DB row to the API response shape (contracts/api.md). */
export function serialize(row) {
  if (!row) return null;
  const tags = getTagsForBookmark(row.id);
  return {
    id: row.id,
    url: row.url,
    title: row.title,
    description: row.description,
    note: row.note_md || null,
    noteHtml: row.note_md ? renderNote(row.note_md) : null,
    faviconUrl: row.favicon_path ? `/snapshots/${row.id}/${row.favicon_path}` : null,
    previewUrl: row.preview_path ? `/snapshots/${row.id}/${row.preview_path}` : null,
    snapshot: {
      kind: row.snapshot_kind,
      status: row.snapshot_status,
      url: row.snapshot_path ? `/snapshots/${row.id}/${row.snapshot_path}` : null,
    },
    archiveOrg: { status: row.archive_org_status, url: row.archive_org_url },
    tags,
    isUnread: !!row.is_unread,
    isArchived: !!row.is_archived,
    createdAt: row.created_at,
    updatedAt: row.updated_at,
  };
}

export function getRowById(id) {
  return stmt('SELECT * FROM bookmarks WHERE id = ?').get(id);
}

export function getById(id) {
  return serialize(getRowById(id));
}

export function getByUrlKey(urlKey) {
  return stmt('SELECT * FROM bookmarks WHERE url_key = ?').get(urlKey);
}

export function create({ url, urlKey, title, description, note, tags, createdAt }) {
  const now = new Date().toISOString();
  const info = stmt(
    `INSERT INTO bookmarks (url, url_key, title, description, note_md, created_at, updated_at)
       VALUES (@url, @urlKey, @title, @description, @note, @createdAt, @now)`
  ).run({
      url,
      urlKey,
      title: title || '',
      description: description || '',
      note: note || null,
      createdAt: createdAt || now,
      now,
    });
  const id = info.lastInsertRowid;
  if (tags && tags.length) setBookmarkTags(id, tags);
  return id;
}

const EDITABLE = ['url', 'url_key', 'title', 'description', 'note_md'];

export function updateFields(id, fields) {
  const sets = [];
  const params = { id, now: new Date().toISOString() };
  for (const [k, v] of Object.entries(fields)) {
    if (EDITABLE.includes(k)) {
      sets.push(`${k} = @${k}`);
      params[k] = v;
    }
  }
  sets.push('updated_at = @now');
  stmt(`UPDATE bookmarks SET ${sets.join(', ')} WHERE id = @id`).run(params);
  return getById(id);
}

export function setEnrichment(
  id,
  { title, description, faviconPath, previewPath, overrideTitle = true, overrideDescription = true }
) {
  const row = getRowById(id);
  if (!row) return;
  // Only fill title/description the user did not provide — user-entered values are
  // never clobbered by auto-collected ones (FR-004). Favicon/preview always update.
  stmt(
    `UPDATE bookmarks
     SET title = CASE WHEN @overrideTitle = 1 THEN COALESCE(NULLIF(@title, ''), title) ELSE title END,
         description = CASE WHEN @overrideDescription = 1 THEN COALESCE(NULLIF(@description, ''), description) ELSE description END,
         favicon_path = COALESCE(@faviconPath, favicon_path),
         preview_path = COALESCE(@previewPath, preview_path),
         updated_at = @now
     WHERE id = @id`
  ).run({
    id,
    title: title || '',
    description: description || '',
    faviconPath: faviconPath || null,
    previewPath: previewPath || null,
    overrideTitle: overrideTitle ? 1 : 0,
    overrideDescription: overrideDescription ? 1 : 0,
    now: new Date().toISOString(),
  });
}

export function setSnapshot(id, { path: snapPath, kind, status }) {
  stmt(
    `UPDATE bookmarks SET snapshot_path = @snapPath, snapshot_kind = @kind,
       snapshot_status = @status, updated_at = @now WHERE id = @id`
  ).run({ id, snapPath: snapPath || null, kind: kind || null, status, now: new Date().toISOString() });
}

export function setArchiveOrg(id, { url, status }) {
  stmt(
    `UPDATE bookmarks SET archive_org_url = @url, archive_org_status = @status,
       updated_at = @now WHERE id = @id`
  ).run({ id, url: url || null, status, now: new Date().toISOString() });
}

export function setReadState(id, unread) {
  stmt('UPDATE bookmarks SET is_unread = ?, updated_at = ? WHERE id = ?').run(
    unread ? 1 : 0,
    new Date().toISOString(),
    id
  );
  return getById(id);
}

export function setArchived(id, archived) {
  stmt('UPDATE bookmarks SET is_archived = ?, updated_at = ? WHERE id = ?').run(
    archived ? 1 : 0,
    new Date().toISOString(),
    id
  );
  return getById(id);
}

export function remove(id) {
  stmt('DELETE FROM bookmarks WHERE id = ?').run(id);
}

/**
 * Build the WHERE clause + params for list/bulk filtering (shared logic).
 * `matchIds` is an optional array of bookmark ids from a search query (null = no text search).
 */
function buildFilter({ includeTags, excludeTags, unread, archived, matchIds }) {
  const clauses = ['b.is_archived = ?'];
  const params = [archived ? 1 : 0];

  if (unread) clauses.push('b.is_unread = 1');

  if (matchIds) {
    if (matchIds.length === 0) return { where: '1 = 0', params: [] };
    clauses.push(`b.id IN (${matchIds.map(() => '?').join(',')})`);
    params.push(...matchIds);
  }

  for (const tag of includeTags || []) {
    clauses.push(
      `EXISTS (SELECT 1 FROM bookmark_tags bt JOIN tags t ON t.id = bt.tag_id
               WHERE bt.bookmark_id = b.id AND t.name = ? COLLATE NOCASE)`
    );
    params.push(tag);
  }
  for (const tag of excludeTags || []) {
    clauses.push(
      `NOT EXISTS (SELECT 1 FROM bookmark_tags bt JOIN tags t ON t.id = bt.tag_id
                   WHERE bt.bookmark_id = b.id AND t.name = ? COLLATE NOCASE)`
    );
    params.push(tag);
  }

  return { where: clauses.join(' AND '), params };
}

export function list(options) {
  const { sort, page = 1, pageSize = 25 } = options;
  const { where, params } = buildFilter(options);
  const total = stmt(`SELECT COUNT(*) AS n FROM bookmarks b WHERE ${where}`).get(...params).n;
  const offset = (Math.max(1, page) - 1) * pageSize;
  const rows = stmt(
    `SELECT b.* FROM bookmarks b WHERE ${where}
       ORDER BY ${sortClause(sort)} LIMIT ? OFFSET ?`
  ).all(...params, pageSize, offset);
  return { items: rows.map(serialize), total };
}

/** Resolve every bookmark id matching a filter (for view-wide bulk actions, FR-027). */
export function resolveIds(options) {
  const { where, params } = buildFilter(options);
  return stmt(`SELECT b.id FROM bookmarks b WHERE ${where}`)
    .all(...params)
    .map((r) => r.id);
}
import { stmt } from '../db/index.js';
import { parseQuery } from '../search/parser.js';

// Execute a parsed search query and return the set of matching bookmark ids.
// Text terms use case-insensitive substring matching across title, description, note,
// and address (FR-014); phrases match the exact substring (FR-016); #tag restricts by
// tag (FR-015). Boolean composition follows the AST (FR-017). Matching spans all
// bookmarks; the caller's list filter applies the archived scope, so the normal list
// excludes archived (FR-019) while the archive view can be searched within.
// Returns null when the query is empty (no text constraint).

function likeEscape(term) {
  return String(term).replace(/[\\%_]/g, (m) => `\\${m}`);
}

function allUniverse() {
  return new Set(stmt('SELECT id FROM bookmarks').all().map((r) => r.id));
}

function matchText(term) {
  const like = `%${likeEscape(term)}%`;
  const rows = stmt(
      `SELECT id FROM bookmarks
       WHERE ( title LIKE @like ESCAPE '\\'
            OR description LIKE @like ESCAPE '\\'
            OR COALESCE(note_md, '') LIKE @like ESCAPE '\\'
            OR url LIKE @like ESCAPE '\\' )`
    )
    .all({ like });
  return new Set(rows.map((r) => r.id));
}

function matchTag(name) {
  const rows = stmt(
      `SELECT b.id FROM bookmarks b
       WHERE EXISTS (SELECT 1 FROM bookmark_tags bt JOIN tags t ON t.id = bt.tag_id
                     WHERE bt.bookmark_id = b.id AND t.name = ? COLLATE NOCASE)`
    )
    .all(name);
  return new Set(rows.map((r) => r.id));
}

function evaluate(node, universe) {
  switch (node.op) {
    case 'term': {
      const { type, value } = node.term;
      if (type === 'tag') return matchTag(value);
      return matchText(value); // word or phrase
    }
    case 'and': {
      const a = evaluate(node.left, universe);
      const b = evaluate(node.right, universe);
      return new Set([...a].filter((id) => b.has(id)));
    }
    case 'or': {
      const a = evaluate(node.left, universe);
      const b = evaluate(node.right, universe);
      return new Set([...a, ...b]);
    }
    case 'not': {
      const c = evaluate(node.child, universe);
      return new Set([...universe].filter((id) => !c.has(id)));
    }
    default:
      return new Set();
  }
}

/**
 * Return an array of matching active bookmark ids for the query string,
 * or null when the query is empty. Throws { code:'invalid_query' } if malformed.
 */
export function searchIds(query) {
  const ast = parseQuery(query);
  if (!ast) return null;
  const universe = allUniverse();
  return [...evaluate(ast, universe)];
}
// Tokenizer for the search grammar (contracts/search-grammar.md).
// Produces tokens: {type:'word'|'phrase'|'tag'|'and'|'or'|'not'|'lparen'|'rparen', value}
// Throws { code:'invalid_query', message } on unbalanced quotes.

const OPERATORS = new Set(['and', 'or', 'not']);

export function tokenize(input) {
  const tokens = [];
  const s = String(input || '');
  let i = 0;

  while (i < s.length) {
    const ch = s[i];

    if (ch === ' ' || ch === '\t' || ch === '\n') {
      i += 1;
      continue;
    }

    if (ch === '(') {
      tokens.push({ type: 'lparen' });
      i += 1;
      continue;
    }
    if (ch === ')') {
      tokens.push({ type: 'rparen' });
      i += 1;
      continue;
    }

    if (ch === '"') {
      // Quoted phrase: captured verbatim; operator words inside are literal text (FR-017c).
      const end = s.indexOf('"', i + 1);
      if (end === -1) {
        const err = new Error('Unbalanced quote in query.');
        err.code = 'invalid_query';
        throw err;
      }
      const value = s.slice(i + 1, end);
      tokens.push({ type: 'phrase', value });
      i = end + 1;
      continue;
    }

    if (ch === '#') {
      let j = i + 1;
      while (j < s.length && !/[\s()"]/.test(s[j])) j += 1;
      const value = s.slice(i + 1, j);
      if (value) tokens.push({ type: 'tag', value });
      i = j;
      continue;
    }

    // Bare run until whitespace or a structural char.
    let j = i;
    while (j < s.length && !/[\s()"]/.test(s[j])) j += 1;
    const raw = s.slice(i, j);
    const lower = raw.toLowerCase();
    if (OPERATORS.has(lower)) {
      tokens.push({ type: lower }); // and | or | not — case-insensitive (FR-017b)
    } else {
      tokens.push({ type: 'word', value: raw });
    }
    i = j;
  }

  return tokens;
}
// Recursive-descent parser building a boolean AST from search tokens.
// Grammar (precedence NOT > AND (incl. implicit) > OR), per contracts/search-grammar.md:
//   or   := and ( OR and )*
//   and  := not ( (AND)? not )*        // adjacent operands => implicit AND (FR-017a)
//   not  := NOT not | atom
//   atom := '(' or ')' | term
// AST nodes:
//   {op:'or'|'and', left, right} | {op:'not', child} | {op:'term', term:{type,value}}
import { tokenize } from './tokenizer.js';

function invalid(message) {
  const err = new Error(message);
  err.code = 'invalid_query';
  return err;
}

const OPERAND_START = new Set(['word', 'phrase', 'tag', 'not', 'lparen']);

export function parseQuery(input) {
  const tokens = tokenize(input);
  if (tokens.length === 0) return null; // empty query = no text constraint

  let pos = 0;
  const peek = () => tokens[pos];
  const next = () => tokens[pos++];

  function parseOr() {
    let node = parseAnd();
    while (peek() && peek().type === 'or') {
      next();
      const right = parseAnd();
      node = { op: 'or', left: node, right };
    }
    return node;
  }

  function parseAnd() {
    let node = parseNot();
    for (;;) {
      const t = peek();
      if (!t) break;
      if (t.type === 'and') {
        next();
        const right = parseNot();
        node = { op: 'and', left: node, right };
      } else if (OPERAND_START.has(t.type)) {
        // Adjacent operand with no operator => implicit AND (FR-017a).
        const right = parseNot();
        node = { op: 'and', left: node, right };
      } else {
        break;
      }
    }
    return node;
  }

  function parseNot() {
    if (peek() && peek().type === 'not') {
      next();
      const child = parseNot();
      return { op: 'not', child };
    }
    return parseAtom();
  }

  function parseAtom() {
    const t = peek();
    if (!t) throw invalid('Unexpected end of query; an operand is missing.');
    if (t.type === 'lparen') {
      next();
      const inner = parseOr();
      const close = next();
      if (!close || close.type !== 'rparen') throw invalid('Unbalanced parentheses in query.');
      return inner;
    }
    if (t.type === 'rparen') throw invalid('Unbalanced parentheses in query.');
    if (t.type === 'and' || t.type === 'or' || t.type === 'not') {
      throw invalid(`Operator "${t.type.toUpperCase()}" is missing an operand.`);
    }
    // word | phrase | tag
    next();
    return { op: 'term', term: { type: t.type, value: t.value } };
  }

  const ast = parseOr();
  if (pos !== tokens.length) throw invalid('Unbalanced parentheses in query.');
  return ast;
}
import React, { useEffect, useState, useCallback } from 'react';
import { useParams, useNavigate, Link, useLocation } from 'react-router-dom';
import { api } from './api.js';
import { BookmarkCard, TagInput, SearchBar, ConfirmDialog, MarkdownNote, StatusBadges } from './components.jsx';

export function markReady() {
  document.documentElement.setAttribute('data-harness-ready', 'true');
}

const SORTS = [
  ['created_desc', 'Newest first'],
  ['created_asc', 'Oldest first'],
  ['title_asc', 'Title A–Z'],
  ['title_desc', 'Title Z–A'],
];

function useListing(fetcher, deps) {
  const [data, setData] = useState({ items: [], total: 0 });
  const [error, setError] = useState(null);
  const [loading, setLoading] = useState(true);
  const reload = useCallback(() => {
    setLoading(true);
    fetcher()
      .then((d) => { setData(d); setError(null); })
      .catch((e) => setError(e.message))
      .finally(() => { setLoading(false); markReady(); });
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, deps);
  useEffect(() => { reload(); }, [reload]);
  return { data, error, loading, reload };
}

// Shared list view used for main list, unread, and archive.
function ListView({ mode }) {
  const location = useLocation();
  const initial = new URLSearchParams(location.search);
  const splitParam = (k) => (initial.get(k) ? initial.get(k).split(',').filter(Boolean) : []);
  const [q, setQ] = useState(initial.get('q') || '');
  const [sort, setSort] = useState(initial.get('sort') || 'created_desc');

  // Initialize the sort control from the user's default-sort preference (FR-042),
  // unless the URL explicitly specifies a sort.
  useEffect(() => {
    if (!initial.get('sort')) {
      api.getPreferences().then((p) => setSort(p.defaultSort)).catch(() => {});
    }
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);
  const [includeTags, setIncludeTags] = useState(splitParam('includeTags'));
  const [excludeTags, setExcludeTags] = useState(splitParam('excludeTags'));
  const [selected, setSelected] = useState(new Set());
  const [toDelete, setToDelete] = useState(null);
  const [bulkTag, setBulkTag] = useState('');
  const [viewName, setViewName] = useState('');

  const params = {
    q,
    sort,
    includeTags: includeTags.join(','),
    excludeTags: excludeTags.join(','),
    unread: mode === 'unread' ? 'true' : undefined,
  };
  const fetcher = () =>
    mode === 'archive' ? api.listArchived(params) : api.listBookmarks(params);
  const { data, error, reload } = useListing(fetcher, [q, sort, includeTags.join(','), excludeTags.join(','), mode]);

  const toggle = (id, on) => {
    const next = new Set(selected);
    if (on) next.add(id); else next.delete(id);
    setSelected(next);
  };

  const runBulk = async (action, extra = {}) => {
    const target = selected.size ? { ids: [...selected] } : { filter: params };
    await api.bulk({ target, action, ...extra });
    setSelected(new Set());
    reload();
  };

  const title = mode === 'unread' ? 'Unread' : mode === 'archive' ? 'Archive' : 'All bookmarks';

  return (
    <div>
      <h2>{title}</h2>
      {error && <div className="error">{error}</div>}
      <div className="toolbar">
        <SearchBar value={q} onSearch={setQ} />
        <select value={sort} onChange={(e) => setSort(e.target.value)} aria-label="sort">
          {SORTS.map(([v, l]) => <option key={v} value={v}>{l}</option>)}
        </select>
      </div>
      <div className="toolbar">
        <span className="muted">Include tags:</span>
        <TagInput tags={includeTags} onChange={setIncludeTags} />
        <span className="muted">Exclude tags:</span>
        <TagInput tags={excludeTags} onChange={setExcludeTags} />
        {(includeTags.length || excludeTags.length || q) ? (
          <button onClick={() => { setIncludeTags([]); setExcludeTags([]); setQ(''); }}>Clear filters</button>
        ) : null}
      </div>

      {mode === 'all' && (
        <div className="toolbar">
          <input type="text" placeholder="save current view as…" value={viewName}
            onChange={(e) => setViewName(e.target.value)} aria-label="save view name" />
          <button disabled={!viewName.trim()} onClick={async () => {
            await api.createView({ name: viewName.trim(), query: q, includeTags, excludeTags, sort });
            setViewName('');
            alert('View saved.');
          }}>Save view</button>
        </div>
      )}

      <div className="bulkbar">
        <span>{selected.size ? `${selected.size} selected` : `Act on all ${data.total} in view`}</span>
        <button onClick={() => runBulk('markUnread')}>Read later</button>
        <button onClick={() => runBulk('markRead')}>Mark read</button>
        {mode === 'archive'
          ? <button onClick={() => runBulk('restore').catch(() => {})} disabled>Restore (per item)</button>
          : <button onClick={() => runBulk('archive')}>Archive</button>}
        <input type="text" placeholder="tag" value={bulkTag} onChange={(e) => setBulkTag(e.target.value)} aria-label="bulk tag" />
        <button disabled={!bulkTag.trim()} onClick={() => { runBulk('addTags', { tags: [bulkTag.trim()] }); setBulkTag(''); }}>Add tag</button>
        <button disabled={!bulkTag.trim()} onClick={() => { runBulk('removeTags', { tags: [bulkTag.trim()] }); setBulkTag(''); }}>Remove tag</button>
        <button className="danger" onClick={() => setToDelete({ bulk: true })}>Delete</button>
      </div>

      {data.items.length === 0 ? (
        <div className="empty">{q ? 'No bookmarks match your search.' : 'No bookmarks yet.'}</div>
      ) : (
        data.items.map((bm) => (
          <BookmarkCard key={bm.id} bm={bm} selectable selected={selected.has(bm.id)}
            onSelect={toggle} onChanged={reload} onDelete={(b) => setToDelete(b)} />
        ))
      )}

      {toDelete && (
        <ConfirmDialog
          message={toDelete.bulk
            ? `Permanently delete ${selected.size ? selected.size : data.total} bookmark(s)? This cannot be undone.`
            : `Permanently delete "${toDelete.title || toDelete.url}"? This cannot be undone.`}
          onCancel={() => setToDelete(null)}
          onConfirm={async () => {
            if (toDelete.bulk) await runBulk('delete');
            else { await api.deleteBookmark(toDelete.id); reload(); }
            setToDelete(null);
          }}
        />
      )}
    </div>
  );
}

export const AllBookmarks = () => <ListView mode="all" />;
export const UnreadView = () => <ListView mode="unread" />;
export const ArchiveView = () => <ListView mode="archive" />;

export function AddBookmark() {
  const [url, setUrl] = useState('');
  const [error, setError] = useState(null);
  const navigate = useNavigate();
  useEffect(() => { markReady(); }, []);

  const save = async () => {
    setError(null);
    try {
      const bm = await api.createBookmark({ url });
      navigate(`/bookmark/${bm.id}`);
    } catch (e) {
      if (e.code === 'duplicate' && e.existingId) {
        navigate(`/bookmark/${e.existingId}?dup=1`);
      } else {
        setError(e.message);
      }
    }
  };

  return (
    <div>
      <h2>Add a bookmark</h2>
      {error && <div className="error">{error}</div>}
      <div className="toolbar">
        <input className="search" type="text" placeholder="https://example.com/article"
          value={url} aria-label="url" onChange={(e) => setUrl(e.target.value)}
          onKeyDown={(e) => { if (e.key === 'Enter') save(); }} />
        <button className="primary" onClick={save} disabled={!url.trim()}>Save</button>
      </div>
      <p className="muted">Title, description, favicon, preview, and a self-contained snapshot are collected automatically.</p>
    </div>
  );
}

export function BookmarkDetail() {
  const { id } = useParams();
  const navigate = useNavigate();
  const [bm, setBm] = useState(null);
  const [error, setError] = useState(null);
  const [form, setForm] = useState({ url: '', title: '', description: '', tags: [] });
  const [toDelete, setToDelete] = useState(false);
  const dup = new URLSearchParams(window.location.hash.split('?')[1] || '').get('dup');

  const load = useCallback(() => {
    api.getBookmark(id).then((b) => {
      setBm(b);
      setForm({ url: b.url, title: b.title, description: b.description, tags: b.tags });
      markReady();
    }).catch((e) => setError(e.message));
  }, [id]);
  useEffect(() => { load(); }, [load]);

  // Poll a few times while enrichment/snapshot are pending.
  useEffect(() => {
    if (!bm) return undefined;
    if (bm.snapshot.status === 'pending' || bm.archiveOrg.status === 'pending') {
      const t = setTimeout(load, 2500);
      return () => clearTimeout(t);
    }
    return undefined;
  }, [bm, load]);

  if (error) return <div className="error">{error}</div>;
  if (!bm) return <div className="empty">Loading…</div>;

